/**
 * Period-length arithmetic and proration shared by the renewal job and the
 * mid-period billing actions (`updateSeats`, `changePlan`).
 *
 * Must call (do not reimplement): getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Advances `start` by one period: a monthly period ends on the same day of
 * the following month (clamped to that month's last day when it has no such
 * day), an annual period on the same day and month a year on. Chaining calls
 * — each one fed the previous result — is what carries a clamped day forward
 * (28 February → 28 March).
 */
export function addPeriod(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInInterval(interval));
}

function addMonthsClamped(date: Date, months: number): Date {
  const targetMonthIndex = date.getUTCMonth() + months;
  const targetYear = date.getUTCFullYear() + Math.floor(targetMonthIndex / 12);
  const normalizedMonth = ((targetMonthIndex % 12) + 12) % 12;
  const daysInTargetMonth = new Date(
    Date.UTC(targetYear, normalizedMonth + 1, 0),
  ).getUTCDate();
  const clampedDay = Math.min(date.getUTCDate(), daysInTargetMonth);

  return new Date(
    Date.UTC(
      targetYear,
      normalizedMonth,
      clampedDay,
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/** The full charge for one period of `plan`, at `seats`, over `interval`. */
export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/** Whole days between `start` and `end`, rounded, at least one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const ms = new Date(end).getTime() - new Date(start).getTime();
  return Math.max(1, Math.round(ms / MS_PER_DAY));
}

/**
 * Whole or started days from `now` to `periodEnd` — 14 days and 22 hours left
 * counts as 15. Zero once the period end has been reached.
 */
export function daysRemaining(now: Date, periodEnd: IsoTimestamp): number {
  const ms = new Date(periodEnd).getTime() - now.getTime();
  return ms <= 0 ? 0 : Math.ceil(ms / MS_PER_DAY);
}

/** `fullChargeCents` scaled by the days left over the days in the period. */
export function prorateCents(
  fullChargeCents: number,
  daysLeft: number,
  totalDays: number,
): number {
  return Math.floor((fullChargeCents * daysLeft) / totalDays);
}

