/**
 * Advances subscription periods and ends due cancellations.
 *
 * Must call (do not reimplement): emit, issueInvoice
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { addPeriod, fullPeriodChargeCents } from "@/server/services/billing-period";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { BillingInterval, Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const FREE_PLAN = "free" as const;
const FREE_INTERVAL: BillingInterval = "monthly";

const logger = createLogger("billing-renewal-job");

/**
 * Every workspace's subscription, once: an `active` one whose period has
 * ended gets one new period per elapsed interval (each paid one invoiced in
 * full), and a `canceled` one whose cancellation date has arrived drops to
 * the free plan as of that date. `trialing` and `past_due` are untouched —
 * that is the trial-expiry job's job. Re-running at the same instant is a
 * no-op: a subscription already caught up to `now` has nothing left to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const nowStamp = toIsoTimestamp(now);
    const subscriptions = await subscriptionRepo.listAllSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const changed =
          subscription.status === "active"
            ? await renewActive(subscription, nowStamp)
            : subscription.status === "canceled"
              ? await endCancellation(subscription, nowStamp)
              : false;

        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

type ElapsedPeriod = { start: IsoTimestamp; end: IsoTimestamp };

/** Rolls `start`/`end` forward one interval at a time until `end` is past `nowStamp`. */
function rollForward(
  start: IsoTimestamp,
  end: IsoTimestamp,
  interval: BillingInterval,
  nowStamp: IsoTimestamp,
): { start: IsoTimestamp; end: IsoTimestamp; elapsed: readonly ElapsedPeriod[] } {
  const elapsed: ElapsedPeriod[] = [];
  let periodStart = start;
  let periodEnd = end;

  while (periodEnd <= nowStamp) {
    elapsed.push({ start: periodStart, end: periodEnd });
    const nextEnd = toIsoTimestamp(addPeriod(new Date(periodEnd), interval));
    periodStart = periodEnd;
    periodEnd = nextEnd;
  }

  return { start: periodStart, end: periodEnd, elapsed };
}

async function renewActive(
  subscription: Subscription,
  nowStamp: IsoTimestamp,
): Promise<boolean> {
  if (subscription.currentPeriodEnd > nowStamp) return false;

  const { start, end, elapsed } = rollForward(
    subscription.currentPeriodStart,
    subscription.currentPeriodEnd,
    subscription.interval,
    nowStamp,
  );

  await subscriptionRepo.applySubscriptionChange(subscription.orgId, {
    currentPeriodStart: start,
    currentPeriodEnd: end,
  });

  if (subscription.plan !== FREE_PLAN) {
    const amount = fullPeriodChargeCents(
      subscription.plan,
      subscription.seats,
      subscription.interval,
    );
    for (const period of elapsed) {
      await issueInvoice(subscription.orgId, amount, period.start, period.end, null);
    }
  }

  return true;
}

async function endCancellation(
  subscription: Subscription,
  nowStamp: IsoTimestamp,
): Promise<boolean> {
  if (subscription.cancelAt === null || subscription.cancelAt > nowStamp) {
    return false;
  }

  const { start, end } = rollForward(
    subscription.cancelAt,
    toIsoTimestamp(addPeriod(new Date(subscription.cancelAt), FREE_INTERVAL)),
    FREE_INTERVAL,
    nowStamp,
  );

  await subscriptionRepo.applySubscriptionChange(subscription.orgId, {
    plan: FREE_PLAN,
    interval: FREE_INTERVAL,
    status: "active",
    cancelAt: null,
    currentPeriodStart: start,
    currentPeriodEnd: end,
  });

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: nowStamp,
    from: subscription.plan,
    to: FREE_PLAN,
  });

  return true;
}

