  });
}

type ElapsedPeriod = { start: IsoTimestamp; end: IsoTimestamp };

/** Rolls `start`/`end` forward one interval at a time until `end` is past `nowStamp`. */
function rollForward(
  start: IsoTimestamp,
  end: IsoTimestamp,
  interval: BillingInterval,
  nowStamp: IsoTimestamp,
): { start: IsoTimestamp; end: IsoTimestamp; elapsed: readonly ElapsedPeriod[] } {
  const elapsed: ElapsedPeriod[] = [];
  let periodStart = start;
  let periodEnd = end;

  while (periodEnd <= nowStamp) {
    elapsed.push({ start: periodStart, end: periodEnd });
    const nextEnd = toIsoTimestamp(addPeriod(new Date(periodEnd), interval));
    periodStart = periodEnd;
    periodEnd = nextEnd;
  }

  return { start: periodStart, end: periodEnd, elapsed };
}

async function renewActive(
  subscription: Subscription,
  nowStamp: IsoTimestamp,
): Promise<boolean> {
  if (subscription.currentPeriodEnd > nowStamp) return false;

  const { start, end, elapsed } = rollForward(
    subscription.currentPeriodStart,
    subscription.currentPeriodEnd,
    subscription.interval,
    nowStamp,
  );

  await subscriptionRepo.applySubscriptionChange(subscription.orgId, {
    currentPeriodStart: start,
    currentPeriodEnd: end,
  });

  if (subscription.plan !== FREE_PLAN) {
    const amount = fullPeriodChargeCents(
      subscription.plan,
      subscription.seats,
      subscription.interval,
    );
    for (const period of elapsed) {
      await issueInvoice(subscription.orgId, amount, period.start, period.end, null);
    }
  }

  return true;
}

async function endCancellation(
  subscription: Subscription,
  nowStamp: IsoTimestamp,
): Promise<boolean> {
  if (subscription.cancelAt === null || subscription.cancelAt > nowStamp) {
    return false;
  }

  const { start, end } = rollForward(
    subscription.cancelAt,
    toIsoTimestamp(addPeriod(new Date(subscription.cancelAt), FREE_INTERVAL)),
    FREE_INTERVAL,
    nowStamp,
  );

  await subscriptionRepo.applySubscriptionChange(subscription.orgId, {
    plan: FREE_PLAN,
    interval: FREE_INTERVAL,
    status: "active",
    cancelAt: null,
    currentPeriodStart: start,
    currentPeriodEnd: end,
  });

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: nowStamp,
    from: subscription.plan,
    to: FREE_PLAN,
  });

  return true;
}

