import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("billing renewal job (scratch verification)", () => {
  it("renews an active paid subscription one period at a time and invoices each", async () => {
    const tenant = await createTenant("renew-1", "starter");
    // starter: trialing by default; force to active with a period in the past.
    await subscriptionRepo.applySubscriptionChange(tenant.org.id, {
      status: "active",
      currentPeriodStart: toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      currentPeriodEnd: toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
      seats: 2,
    });

    const now = new Date("2026-04-15T00:00:00.000Z");
    const result = await runBillingRenewalJob(now);
    expect(result.failed).toBe(0);

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    console.log("subscription after renewal", sub);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    console.log(
      "invoices",
      invoices.map((i) => ({ number: i.number, amount: i.amountCents, start: i.periodStart, end: i.periodEnd })),
    );

    // Replay: run again at same instant, nothing should change.
    const invoiceCountBefore = invoices.length;
    const result2 = await runBillingRenewalJob(now);
    const invoicesAfterReplay = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoicesAfterReplay.length).toBe(invoiceCountBefore);
    console.log("replay result", result2);
  });

  it("ends a cancellation and moves the workspace to free", async () => {
    const tenant = await createTenant("renew-2", "growth");
    await subscriptionRepo.applySubscriptionChange(tenant.org.id, {
