import { describe, expect, it } from "vitest";
import { addPeriod } from "@/server/services/billing-period";

describe("addPeriod (scratch verification)", () => {
  it("clamps 31 Jan to 28 Feb for a monthly period", () => {
    const end = addPeriod(new Date("2026-01-31T10:00:00.000Z"), "monthly");
    expect(end.toISOString()).toBe("2026-02-28T10:00:00.000Z");
  });

  it("carries the clamped day forward: 28 Feb -> 28 Mar", () => {
    const end = addPeriod(new Date("2026-02-28T10:00:00.000Z"), "monthly");
    expect(end.toISOString()).toBe("2026-03-28T10:00:00.000Z");
  });

  it("clamps 29 Feb (leap) to 28 Feb next year for an annual period", () => {
    const end = addPeriod(new Date("2028-02-29T10:00:00.000Z"), "annual");
    expect(end.toISOString()).toBe("2029-02-28T10:00:00.000Z");
  });

  it("annual period on a non-clamped day lands on the same day next year", () => {
    const end = addPeriod(new Date("2026-03-15T10:00:00.000Z"), "annual");
    expect(end.toISOString()).toBe("2027-03-15T10:00:00.000Z");
  });
});

